CREATE TABLE search_state (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('notes','vocab')),query TEXT NOT NULL,PRIMARY KEY(user_id,kind));
CREATE TABLE reminder_drafts (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,id TEXT NOT NULL,content TEXT NOT NULL,due_at INTEGER NOT NULL,note_id TEXT REFERENCES notes(id) ON DELETE SET NULL,expires INTEGER NOT NULL);
